def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C' if history[0][1] == 'C' else 'D'
    if n == 2:
        return 'C' if history[1][1] == 'C' else 'D'
    if n == 3:
        return 'D'
    if n == 4:
        if history[3][0] == 'D' and history[3][1] == 'C':
            return 'C'

    opp_def_count = 0
    for me, opp in history:
        if opp == 'D':
            opp_def_count += 1

    probed = False
    for me, opp in history:
        if me == 'D' and opp == 'C':
            probed = True
            break

    retaliated = False
    for i in range(n - 1):
        if history[i][0] == 'D' and history[i][1] == 'C' and history[i+1][1] == 'D':
            retaliated = True
            break

    if probed and not retaliated:
        return 'D'

    if n >= 99:
        return 'D'
    if n == 98:
        recent_coop = 0
        start = n - 10 if n > 10 else 0
        for i in range(start, n):
            if history[i][1] == 'C':
                recent_coop += 1
        if recent_coop > 3:
            return 'C'
        else:
            return 'D'

    last_me, last_opp = history[-1]
    opp_coop_rate = (n - opp_def_count) / n

    opp_def_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_def_streak += 1
        else:
            break

    if opp_def_streak >= 3:
        return 'D'

    if opp_coop_rate < 0.25:
        return 'D'

    if last_opp == 'D':
        if n >= 2 and history[-2][0] == 'D':
            return 'C'
        else:
            return 'D'
    else:
        return 'C'
